#include <iostream>
using namespace std;
int main() {
    int n, x, y;
    cin >> n >> x >> y;
    int pingguo;
    if (y % x == 0) {
        pingguo = n - y / x;
    } else {
        pingguo = n - y / x - 1;
    }
    if (pingguo < 0) {
        cout << 0;
    } else {
        cout << pingguo;
    }
    return 0;
}
